    for key in limiter._windows:
        start, _ = limiter._windows[key]
        limiter._windows[key] = (start - 61, 1)

    assert limiter.allow("ip") is True


def test_limiter_reset():
    limiter = RateLimiter(max_requests=1, window_seconds=60)
    assert limiter.allow("ip") is True
    limiter.reset()
    assert limiter.allow("ip") is True


